#!/usr/bin/env python3
"""Every password for the migration, generated by Secrets Manager and stored in ONE secret. Nothing is typed or shown.

  python3 scripts/secret.py create <secret-name>    generate the passwords, store them, print only the secret's ARN
  python3 scripts/secret.py get <key>               print one password (only ever used inside $( ... ))
  python3 scripts/secret.py keys                    list the keys (not the values)

Keys: source_root (MySQL root on the source), dms_source (the DMS reader), app (the order application),
aurora_admin (Aurora master user), pg_admin (PostgreSQL master user).
"""
import json, sys
from kit_aws import aws, env

KEYS = ["source_root", "dms_source", "app", "aurora_admin", "pg_admin"]


def new_password():
    # Letters and digits only: nothing a shell, a SQL string or a connection string can misread.
    return aws("secretsmanager", "get-random-password", "--password-length", "28",
               "--exclude-punctuation", "--require-each-included-type")["RandomPassword"]


def main():
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    cmd = sys.argv[1]
    if cmd == "create":
        name = sys.argv[2]
        value = json.dumps({k: new_password() for k in KEYS})
        arn = aws("secretsmanager", "create-secret", "--name", name,
                  "--description", "Ubuntu Retail order DB migration passwords", "--secret-string", value)["ARN"]
        print(arn)
    elif cmd == "get":
        key = sys.argv[2]
        data = json.loads(aws("secretsmanager", "get-secret-value", "--secret-id", env("SECRET_ID"))["SecretString"])
        if key not in data:
            sys.exit(f"no key {key!r}; keys are {', '.join(data)}")
        print(data[key])
    elif cmd == "keys":
        data = json.loads(aws("secretsmanager", "get-secret-value", "--secret-id", env("SECRET_ID"))["SecretString"])
        print(", ".join(f"{k} ({len(v)} characters)" for k, v in data.items()))
    else:
        sys.exit(__doc__)


if __name__ == "__main__":
    main()
